    name: `${sn.title} — UI Snippets`,
    url: `${BASE_URL}/${slug}/`,
    applicationCategory: 'DeveloperApplication',
    operatingSystem: 'Web',
    offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' },
    description: `Free copy-paste ${sn.title} snippet. Edit HTML, CSS${sn.js ? ', JS' : ''} with live preview.`,
